/** The same as a data URL (for the dialog box, the place bar and the map). */
function keeperImage(id, blink = false, S = 1) {
  if (!KEEPER_ART[id]) return pxIcon(id);
  const key = `url|${id}|${blink ? 1 : 0}|${S}`;
  return keeperCache[key] || (keeperCache[key] = keeperCanvas(id, blink, S).toDataURL());
}
/** Just the head and shoulders, for the dialog box. */
function keeperFace(id) {
  const key = id + ":face";
  if (keeperCache[key]) return keeperCache[key];
  if (!KEEPER_ART[id]) return pxIcon(id);
  const c = document.createElement("canvas"); c.width = c.height = 52;
  if (KEEPER_NATIVE[id]) {
    // head and shoulders at twice size: the 26 rows from the top of the head, centred on it
    const full = keeperNative(id), d = full.getContext("2d").getImageData(0, 0, full.width, full.height).data, w = full.width;
    let top = 0; while (top < full.height && ![...Array(w).keys()].some(x => d[(top * w + x) * 4 + 3] > 128)) top++;
    let sx = 0, n = 0; for (let y = top; y < Math.min(full.height, top + 18); y++) for (let x = 0; x < w; x++) if (d[(y * w + x) * 4 + 3] > 128) { sx += x; n++; }
    const cx = n ? Math.round(sx / n) : w / 2, g = c.getContext("2d"); g.imageSmoothingEnabled = false;
    g.drawImage(full, cx - 13, Math.max(0, top - 2), 26, 26, 0, 0, 52, 52);
    return keeperCache[key] = c.toDataURL();
  }
  // head and shoulders, drawn twice as fine as the small version
  const full = keeperCanvas(id, false, 2);
  c.getContext("2d").drawImage(full, -14, -2);
  return keeperCache[key] = c.toDataURL();
}
/** A tiny keeper for the map: a third the size, each map pixel the colour most of its 3×3 block has. */
function keeperMini(id) {
  const key = id + ":mini";
  if (keeperCache[key]) return keeperCache[key];
  if (!KEEPER_ART[id]) return pxIcon(id);
  const full = KEEPER_NATIVE[id] ? keeperNative(id) : keeperCanvas(id, false, 1), FW = full.width, FH = full.height, B = KEEPER_NATIVE[id] ? 4 : 3;
  const d = full.getContext("2d").getImageData(0, 0, FW, FH).data, w = Math.ceil(FW / B), h = Math.ceil(FH / B);
  const c = document.createElement("canvas"); c.width = w; c.height = h; const g = c.getContext("2d"), im = g.createImageData(w, h);
  for (let y = 0; y < h; y++) for (let x = 0; x < w; x++) {
    const seen = new Map(); let opaque = 0;
    for (let j = 0; j < B; j++) for (let i = 0; i < B; i++) { const X = x * B + i, Y = y * B + j; if (X >= FW || Y >= FH) continue; const o = (Y * FW + X) * 4; if (d[o + 3] < 128) continue; opaque++; const key2 = (d[o] << 16) | (d[o + 1] << 8) | d[o + 2]; seen.set(key2, (seen.get(key2) || 0) + (key2 === 0x0b0614 ? 0.6 : 1)); }
    if (opaque < B * B * 0.45) continue;
    const best = [...seen].sort((p, q) => q[1] - p[1])[0][0], o = (y * w + x) * 4;
    im.data[o] = best >> 16; im.data[o + 1] = (best >> 8) & 255; im.data[o + 2] = best & 255; im.data[o + 3] = 255;
  }
  g.putImageData(im, 0, 0);
  return keeperCache[key] = c.toDataURL();
}
